import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));

        // Transfer ownership to newOwner, then call owned() as newOwner.
        // On the reference C, the call succeeds (onlyOwner modifier passes).
        // On the buggy version, the call reverts (require(msg.sender != owner) fails).
        vm.prank(address(this));
        c.transferOwnership(newOwner);

        vm.prank(newOwner);
        bool ok;
        try c.owned() {
            ok = true;
        } catch {
            ok = false;
        }
        // ownership was transferred to newOwner, so newOwner IS the owner.
        assertTrue(ok);
    }
}

