pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // 1. Restrict caller to be distinct from the current owner to test unauthorized behavior.
        vm.assume(caller != c.owner());

        bool success;
        address ownerBefore = c.owner();

        // 2. Attempt transferOwnership as the non-owner caller
        vm.prank(caller);
        try c.transferOwnership(address(0x1)) {
            success = true;
        } catch {
            success = false;
        }

        // 3. General rule: For unauthorized calls, the call never panics and owner remains unchanged.
        // The mutant panics on unauthorized call, causing the catch block to trigger a revert with Panic(uint256),
        // which changes the observable behavior.
        assertTrue(!success && ownerBefore == c.owner());
    }
}

