pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        bool ok;
        vm.prank(caller);
        try c.transferOwnership(address(1)) {
            ok = true;
        } catch (bytes memory err) {
            ok = false;
            // If it reverted, ensure it's NOT a panic (Panic(uint256) has selector 0x4e487b71)
            bytes4 panicSelector = bytes4(keccak256("Panic(uint256)"));
            if (err.length >= 4 && bytes4(err) == panicSelector) {
                ok = false;
            } else {
                ok = true; // non-panic revert is acceptable
            }
        }
        // The call must not panic. It can succeed (if caller==owner) or revert non-panically (if unauthorized).
        assertTrue(ok);
    }
}

