contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonOwner, address newOwner) public {
        // Ensure non-owner is not the current owner
        vm.assume(nonOwner != c.owner());
        // Ensure new owner is different from current owner to observe potential change
        vm.assume(newOwner != c.owner());
        // Avoid the zero address as owner for cleaner semantics
        vm.assume(nonOwner != address(0));
        vm.assume(newOwner != address(0));

        address initialOwner = c.owner();
        vm.prank(nonOwner);
        c.transferOwnership(newOwner);

        // The correct contract must preserve the original owner when called by a non-owner
        assertTrue(c.owner() == initialOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, address nonOwner, address newOwner) public {
        vm.assume(owner != nonOwner);
        vm.assume(nonOwner != address(0));
        vm.assume(owner != address(0));
        vm.assume(newOwner != owner);

        // Set the initial owner to 'owner'
        vm.prank(address(this));
        c.transferOwnership(owner);

        // Now attempt a transfer as the non-owner
        vm.prank(nonOwner);
        (bool success, bytes memory returnData) = address(c).call(
            abi.encodeWithSelector(c.transferOwnership.selector, newOwner)
        );
        // In the reference contract this must revert; in the mutant it can succeed.
        // If success==true, a revert has NOT occurred.
        // Therefore the assertion: the call must NOT succeed (i.e., success must be false).
        assertTrue(!success);
    }
}
